import{_ as a,o as l,c as e,a4 as r}from"./chunks/framework.9tZL7ZIQ.js";const b=JSON.parse('{"title":"华盛顿邮报（Washington Post）","description":"","frontmatter":{},"headers":[],"relativePath":"03_companies/华盛顿邮报.md","filePath":"03_companies/华盛顿邮报.md"}'),o={name:"03_companies/华盛顿邮报.md"};function d(i,t,h,n,u,s){return l(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="华盛顿邮报-washington-post" tabindex="-1">华盛顿邮报（Washington Post） <a class="header-anchor" href="#华盛顿邮报-washington-post" aria-label="Permalink to &quot;华盛顿邮报（Washington Post）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>英文名</td><td>Washington Post Company</td></tr><tr><td>行业</td><td>媒体/出版</td></tr><tr><td>成立年份</td><td>1877年</td></tr><tr><td>总部</td><td>华盛顿特区</td></tr><tr><td>伯克希尔持股</td><td>1,727,765股（约18%股权）</td></tr><tr><td>投资成本</td><td>约1,063万美元（1973年买入）</td></tr><tr><td>持仓峰值市值</td><td>约14亿美元（2013年出售前）</td></tr><tr><td>投资收益</td><td>超过100倍</td></tr><tr><td>持有年限</td><td>1973年-2013年（40年）</td></tr></tbody></table><h2 id="核心业务" tabindex="-1">核心业务 <a class="header-anchor" href="#核心业务" aria-label="Permalink to &quot;核心业务&quot;">​</a></h2><p>华盛顿邮报公司是美国领先的媒体集团，核心业务包括：</p><ul><li><strong>《华盛顿邮报》报纸</strong>：华盛顿特区主要日报，拥有极高渗透率</li><li><strong>广播电视</strong>：拥有多家电视台</li><li><strong>杂志出版</strong>：《新闻周刊》等</li><li><strong>教育服务</strong>：Kaplan教育部门（后成为重要增长引擎）</li></ul><p>2013年，公司拆分报纸业务（出售给杰夫·贝索斯），剩余业务更名为Graham Holdings。</p><h2 id="投资历程" tabindex="-1">投资历程 <a class="header-anchor" href="#投资历程" aria-label="Permalink to &quot;投资历程&quot;">​</a></h2><h3 id="买入背景-1973年" tabindex="-1">买入背景（1973年） <a class="header-anchor" href="#买入背景-1973年" aria-label="Permalink to &quot;买入背景（1973年）&quot;">​</a></h3><ul><li><strong>1973年年中</strong>：巴菲特开始买入华盛顿邮报B类股票</li><li><strong>买入价格</strong>：成本约1,063万美元，买入约46.7万股</li><li><strong>买入时市值</strong>：约8,000万-1亿美元</li><li><strong>内在价值</strong>：巴菲特估算约4-5亿美元</li><li><strong>安全边际</strong>：买入价不到内在价值的<strong>四分之一</strong></li></ul><p>巴菲特在1985年股东信中详细解释了买入背景：</p><blockquote><p>&quot;我们1973年年中买入华盛顿邮报，买入价不到我们认为它每股business价值四分之一。计算价格价值比不需要什么非凡洞察力，大多数证券分析师媒体高管，都能算出来华盛顿邮报内在价值4-5亿美元，市场当时总市值就是1亿美元。&quot;</p></blockquote><p><strong>市场错误定价的原因</strong>：</p><ol><li>机构投资者被有效市场理论&quot;洗脑&quot;，认为计算企业价值无用</li><li>报纸行业遭遇罢工等负面事件，市场过度恐慌</li><li>1973-1974年熊市，股价持续下跌</li></ol><h3 id="持股演变完整时间线" tabindex="-1">持股演变完整时间线 <a class="header-anchor" href="#持股演变完整时间线" aria-label="Permalink to &quot;持股演变完整时间线&quot;">​</a></h3><table tabindex="0"><thead><tr><th>年份</th><th>持股数</th><th>成本（万美元）</th><th>市值（万美元）</th><th>备注</th></tr></thead><tbody><tr><td>1973年</td><td>467,150</td><td>1,060</td><td>-</td><td>首次买入</td></tr><tr><td>1975年</td><td>467,150</td><td>1,060</td><td>-</td><td>首次披露，计划&quot;永久持有&quot;</td></tr><tr><td>1977年</td><td>934,300</td><td>1,063</td><td>-</td><td>大幅增持</td></tr><tr><td>1979年</td><td>1,868,000</td><td>1,063</td><td>-</td><td>继续增持</td></tr><tr><td>1985年</td><td>1,727,765</td><td>973</td><td>22,100</td><td>比例赎回后持股</td></tr><tr><td>1987年</td><td>1,727,765</td><td>973</td><td>32,600</td><td>持续增值</td></tr><tr><td>1991年</td><td>1,727,765</td><td>973</td><td>33,610</td><td>媒体行业估值下降</td></tr><tr><td>1993年</td><td>1,727,765</td><td>973</td><td>44,015</td><td>透视盈利1,500万</td></tr><tr><td>1996年</td><td>1,727,765</td><td>1,060</td><td>57,900</td><td>-</td></tr><tr><td>2006年</td><td>1,727,765</td><td>1,100</td><td>128,800</td><td>-</td></tr><tr><td>2013年</td><td>-</td><td>-</td><td>出售</td><td>约14亿美元</td></tr></tbody></table><h3 id="投资逻辑" tabindex="-1">投资逻辑 <a class="header-anchor" href="#投资逻辑" aria-label="Permalink to &quot;投资逻辑&quot;">​</a></h3><p>巴菲特在多封股东信中阐述了对华盛顿邮报的投资逻辑：</p><h4 id="_1-优秀的企业品质" tabindex="-1">1. 优秀的企业品质 <a class="header-anchor" href="#_1-优秀的企业品质" aria-label="Permalink to &quot;1. 优秀的企业品质&quot;">​</a></h4><blockquote><p>&quot;华盛顿邮报是我们最满意的投资之一，拥有优秀的企业和优秀的管理层。&quot; —— 1984年股东信</p></blockquote><h4 id="_2-地理垄断优势" tabindex="-1">2. 地理垄断优势 <a class="header-anchor" href="#_2-地理垄断优势" aria-label="Permalink to &quot;2. 地理垄断优势&quot;">​</a></h4><ul><li>华盛顿特区唯一主流日报</li><li>高渗透率市场，工作日渗透率全美前50大报最高</li><li>首都主要媒体，政策新闻报道优势</li></ul><h4 id="_3-优秀的管理层" tabindex="-1">3. 优秀的管理层 <a class="header-anchor" href="#_3-优秀的管理层" aria-label="Permalink to &quot;3. 优秀的管理层&quot;">​</a></h4><p>巴菲特对凯瑟琳·格雷厄姆的评价：</p><blockquote><p>&quot;凯瑟琳·格雷厄姆有勇气回购大量股票，这个决策比大多数媒体公司管理者好太多。她这个成就应该让更多伯克希尔股东知道。&quot; —— 1985年股东信</p></blockquote><h4 id="_4-股东导向的资本配置" tabindex="-1">4. 股东导向的资本配置 <a class="header-anchor" href="#_4-股东导向的资本配置" aria-label="Permalink to &quot;4. 股东导向的资本配置&quot;">​</a></h4><blockquote><p>&quot;我们三大持仓GEICO、华盛顿邮报、通用食品，都大幅低价回购，股东利益显著提升，我们拿着非常舒服。&quot; —— 1984年股东信</p></blockquote><h3 id="关键事件-1985年比例赎回" tabindex="-1">关键事件：1985年比例赎回 <a class="header-anchor" href="#关键事件-1985年比例赎回" aria-label="Permalink to &quot;关键事件：1985年比例赎回&quot;">​</a></h3><p>1985年，华盛顿邮报进行股票回购，巴菲特参与&quot;比例赎回&quot;：</p><ul><li>公司回购股票，巴菲特按比例卖出一部分</li><li>保持持股比例不变（约18%）</li><li>获得约1,488万美元特别分红</li><li>IRS认定此类交易为分红而非资本利得，税收更优惠</li></ul><p>巴菲特在1985年股东信中详细说明了这一交易：</p><blockquote><p>&quot;我们拿到三重好处：企业内在价值上涨，回购进一步提升每股内在价值，估值折价慢慢缩小，股价涨得比内在价值快。&quot;</p></blockquote><h3 id="价值增长三重驱动" tabindex="-1">价值增长三重驱动 <a class="header-anchor" href="#价值增长三重驱动" aria-label="Permalink to &quot;价值增长三重驱动&quot;">​</a></h3><p>巴菲特在1985年股东信中总结华盛顿邮报投资的&quot;三重好处&quot;：</p><blockquote><p>&quot;我们拿到三重好处：企业内在价值上涨，回购进一步提升每股内在价值，估值折价慢慢缩小，股价涨得比内在价值快。&quot;</p></blockquote><p>具体来说：</p><p><strong>第一重：企业内在价值增长</strong></p><ul><li>1973年内在价值4-5亿美元，市值1亿美元</li><li>1985年内在价值继续增长</li></ul><p><strong>第二重：回购提升每股价值</strong></p><ul><li>华盛顿邮报在股价低估时大量回购</li><li>巴菲特持股比例保持不变</li><li>每股代表的价值增加</li></ul><p><strong>第三重：估值修复</strong></p><ul><li>从大幅折价到合理估值</li><li>股价涨幅超过内在价值涨幅</li></ul><h3 id="早期持股与个人渊源" tabindex="-1">早期持股与个人渊源 <a class="header-anchor" href="#早期持股与个人渊源" aria-label="Permalink to &quot;早期持股与个人渊源&quot;">​</a></h3><p>巴菲特在1995年股东信中揭示了一段有趣的个人渊源：</p><blockquote><p>&quot;我购买GEICO股票所用的大部分资金是靠送华盛顿邮报赚来的——华盛顿邮报是华盛顿邮报公司的旗舰产品，而多年后正是这家公司使伯克希尔得以将1,000万美元变成5亿美元。&quot;</p></blockquote><h3 id="_1975年养老金备忘录" tabindex="-1">1975年养老金备忘录 <a class="header-anchor" href="#_1975年养老金备忘录" aria-label="Permalink to &quot;1975年养老金备忘录&quot;">​</a></h3><p>巴菲特在2013年股东信中提到了他与华盛顿邮报的重要交集：</p><blockquote><p>&quot;1975年，我给凯瑟琳·格雷厄姆——当时华盛顿邮报公司董事长——写了一份备忘录，关于养老金承诺的陷阱和投资政策的重要性。该备忘录转载于第118-136页。&quot;</p></blockquote><p>这份备忘录后来被巴菲特认为是重要的历史文献，显示了他对被投资公司治理的深度参与。</p><h2 id="与巴菲特的关系" tabindex="-1">与巴菲特的关系 <a class="header-anchor" href="#与巴菲特的关系" aria-label="Permalink to &quot;与巴菲特的关系&quot;">​</a></h2><h3 id="董事会成员" tabindex="-1">董事会成员 <a class="header-anchor" href="#董事会成员" aria-label="Permalink to &quot;董事会成员&quot;">​</a></h3><p>巴菲特于1974年加入华盛顿邮报董事会，长期担任董事。他在1985年因购买首都城市/ABC而辞去董事职位，但保留了股票：</p><blockquote><p>&quot;我们买首都城市/ABC，需要我提前离开华盛顿邮报董事会，我们会继续持有华盛顿邮报股票，FCC规则允许我们拿多少我们就拿多少。&quot; —— 1985年股东信</p></blockquote><h3 id="与凯瑟琳·格雷厄姆的关系" tabindex="-1">与凯瑟琳·格雷厄姆的关系 <a class="header-anchor" href="#与凯瑟琳·格雷厄姆的关系" aria-label="Permalink to &quot;与凯瑟琳·格雷厄姆的关系&quot;">​</a></h3><p>巴菲特与华盛顿邮报发行人<a href="/04_people/凯瑟琳·格雷厄姆.html">凯瑟琳·格雷厄姆</a>建立了深厚的友谊和商业关系：</p><ul><li>长期担任公司董事和顾问</li><li>在关键决策（如股票回购）上提供支持</li><li>1975年为格雷厄姆撰写关于养老金投资政策的重要备忘录</li><li>两人保持了终生的友谊和商业伙伴关系</li></ul><h3 id="永久持仓-承诺" tabindex="-1">&quot;永久持仓&quot;承诺 <a class="header-anchor" href="#永久持仓-承诺" aria-label="Permalink to &quot;&quot;永久持仓&quot;承诺&quot;">​</a></h3><p>华盛顿邮报是巴菲特明确宣布&quot;永久持有&quot;的三只股票之一：</p><blockquote><p>&quot;我们年底三大主要持仓，首都城市/ABC，GEICO，华盛顿邮报，我们预计永远持有，哪怕它们现在明显高估，我们也不会卖。&quot; —— 1986年股东信</p></blockquote><h2 id="核心竞争优势" tabindex="-1">核心竞争优势 <a class="header-anchor" href="#核心竞争优势" aria-label="Permalink to &quot;核心竞争优势&quot;">​</a></h2><h3 id="_1-地理垄断" tabindex="-1">1. 地理垄断 <a class="header-anchor" href="#_1-地理垄断" aria-label="Permalink to &quot;1. 地理垄断&quot;">​</a></h3><ul><li>华盛顿特区唯一主流日报</li><li>工作日渗透率全美前50大报最高（<a href="/03_companies/水牛城新闻.html">水牛城新闻</a>也是第一）</li><li>&quot;垄断或接近垄断&quot;的报纸经济特征</li></ul><h3 id="_2-管理质量" tabindex="-1">2. 管理质量 <a class="header-anchor" href="#_2-管理质量" aria-label="Permalink to &quot;2. 管理质量&quot;">​</a></h3><ul><li>凯瑟琳·格雷厄姆决策能力强</li><li>敢于在低价回购大量股票</li><li>后来其子唐纳德·格雷厄姆延续了股东导向传统</li></ul><h3 id="_3-政治影响力" tabindex="-1">3. 政治影响力 <a class="header-anchor" href="#_3-政治影响力" aria-label="Permalink to &quot;3. 政治影响力&quot;">​</a></h3><ul><li>首都主要媒体</li><li>政策新闻报道优势</li><li>&quot;水门事件&quot;等标志性报道建立了品牌影响力</li></ul><h3 id="_4-财务纪律" tabindex="-1">4. 财务纪律 <a class="header-anchor" href="#_4-财务纪律" aria-label="Permalink to &quot;4. 财务纪律&quot;">​</a></h3><ul><li>低负债运营</li><li>积极回购低估股票</li><li>留存收益高效再投资</li></ul><h2 id="巴菲特评价摘录" tabindex="-1">巴菲特评价摘录 <a class="header-anchor" href="#巴菲特评价摘录" aria-label="Permalink to &quot;巴菲特评价摘录&quot;">​</a></h2><h3 id="关于投资机会" tabindex="-1">关于投资机会 <a class="header-anchor" href="#关于投资机会" aria-label="Permalink to &quot;关于投资机会&quot;">​</a></h3><blockquote><p>&quot;1973年我们买入华盛顿邮报时，买入价不到内在价值的四分之一。&quot; —— 1985年股东信</p></blockquote><h3 id="关于市场错误定价" tabindex="-1">关于市场错误定价 <a class="header-anchor" href="#关于市场错误定价" aria-label="Permalink to &quot;关于市场错误定价&quot;">​</a></h3><blockquote><p>&quot;那时候机构投资者被顶尖商学院学术理论洗脑，说股市完全有效，算business价值没用，所以我们能捡便宜，我们非常感谢这些学术界，对手都信了有效市场，我们才能赢。&quot; —— 1985年股东信</p></blockquote><h3 id="关于管理层" tabindex="-1">关于管理层 <a class="header-anchor" href="#关于管理层" aria-label="Permalink to &quot;关于管理层&quot;">​</a></h3><blockquote><p>&quot;华盛顿邮报管理层，热爱生意，像所有者一样思考，诚信能力都够。&quot; —— 1988年股东信</p></blockquote><h3 id="关于长期持有" tabindex="-1">关于长期持有 <a class="header-anchor" href="#关于长期持有" aria-label="Permalink to &quot;关于长期持有&quot;">​</a></h3><blockquote><p>&quot;卖出一家可辨识的卓越公司的股权是不明智的。&quot; —— 1993年股东信</p></blockquote><h3 id="关于投资教训" tabindex="-1">关于投资教训 <a class="header-anchor" href="#关于投资教训" aria-label="Permalink to &quot;关于投资教训&quot;">​</a></h3><blockquote><p>&quot;有趣的是，企业管理者在专注于他们经营的业务时毫不费力地理解这一点：拥有一家具有卓越长期经济特征的子公司的母公司不太可能出售该实体，无论价格如何。&quot; —— 1993年股东信</p></blockquote><h3 id="关于早期送报经历" tabindex="-1">关于早期送报经历 <a class="header-anchor" href="#关于早期送报经历" aria-label="Permalink to &quot;关于早期送报经历&quot;">​</a></h3><blockquote><p>&quot;我购买GEICO股票所用的大部分资金是靠送华盛顿邮报赚来的——华盛顿邮报是华盛顿邮报公司的旗舰产品，而多年后正是这家公司使伯克希尔得以将1,000万美元变成5亿美元。&quot; —— 1995年股东信</p></blockquote><h3 id="关于风险与机会" tabindex="-1">关于风险与机会 <a class="header-anchor" href="#关于风险与机会" aria-label="Permalink to &quot;关于风险与机会&quot;">​</a></h3><blockquote><p>&quot;对于企业所有者——而这正是我们看待股东的方式——学术界对风险的定义完全偏离了目标，其偏离程度甚至产生了荒谬的结果。例如，根据基于贝塔系数的理论，与市场相比大幅下跌的股票——就像1973年我们买入华盛顿邮报时那样——在更低的价格时比在更高价格时&#39;风险更大&#39;。&quot; —— 1993年股东信</p></blockquote><h3 id="关于geico与华盛顿邮报的渊源" tabindex="-1">关于GEICO与华盛顿邮报的渊源 <a class="header-anchor" href="#关于geico与华盛顿邮报的渊源" aria-label="Permalink to &quot;关于GEICO与华盛顿邮报的渊源&quot;">​</a></h3><blockquote><p>&quot;1951年1月，我乘火车前往华盛顿，直奔GEICO的市中心总部……在那次会面之后，我对GEICO的热情超过了我对任何一只股票的热情……我购买GEICO股票所用的大部分资金是靠送华盛顿邮报赚来的——华盛顿邮报是华盛顿邮报公司的旗舰产品，而多年后正是这家公司使伯克希尔得以将1,000万美元变成5亿美元。&quot; —— 1995年股东信</p></blockquote><h2 id="财务表现" tabindex="-1">财务表现 <a class="header-anchor" href="#财务表现" aria-label="Permalink to &quot;财务表现&quot;">​</a></h2><h3 id="持仓市值变化" tabindex="-1">持仓市值变化 <a class="header-anchor" href="#持仓市值变化" aria-label="Permalink to &quot;持仓市值变化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>年份</th><th>持股市值（万美元）</th><th>年复利回报（自1973年）</th></tr></thead><tbody><tr><td>1985</td><td>22,100</td><td>约26%</td></tr><tr><td>1987</td><td>32,600</td><td>约28%</td></tr><tr><td>1991</td><td>33,610</td><td>约17%</td></tr><tr><td>1996</td><td>57,900</td><td>约16%</td></tr><tr><td>2006</td><td>128,800</td><td>约11%</td></tr><tr><td>2013</td><td>约140,000</td><td>约12%</td></tr></tbody></table><h3 id="透视盈利贡献" tabindex="-1">透视盈利贡献 <a class="header-anchor" href="#透视盈利贡献" aria-label="Permalink to &quot;透视盈利贡献&quot;">​</a></h3><p>华盛顿邮报是伯克希尔&quot;透视盈利&quot;的重要组成部分：</p><table tabindex="0"><thead><tr><th>年份</th><th>占股比例</th><th>未分配盈利（百万美元）</th></tr></thead><tbody><tr><td>1992</td><td>14.6%</td><td>11</td></tr><tr><td>1993</td><td>14.8%</td><td>15</td></tr><tr><td>1994</td><td>15.2%</td><td>18</td></tr><tr><td>1996</td><td>15.8%</td><td>27</td></tr><tr><td>1997</td><td>16.5%</td><td>30</td></tr></tbody></table><h3 id="回购带来的好处" tabindex="-1">回购带来的好处 <a class="header-anchor" href="#回购带来的好处" aria-label="Permalink to &quot;回购带来的好处&quot;">​</a></h3><p>巴菲特在1997年股东信中强调回购对长期股东的价值：</p><blockquote><p>&quot;通过伯克希尔，你们拥有那些持续回购股份的大型公司的重要头寸。这些计划给我们带来的好处在价格下跌时增长：当股票价格低时，被投资公司用于回购的资金与我们拥有的该公司股权增加的幅度，要比价格高时更大。例如，可口可乐、华盛顿邮报和富国银行在过去以非常低的价格进行的回购，使伯克希尔受益远比今天以更高价格进行的回购大得多。&quot;</p></blockquote><h2 id="相关人物" tabindex="-1">相关人物 <a class="header-anchor" href="#相关人物" aria-label="Permalink to &quot;相关人物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>姓名</th><th>职位</th><th>与巴菲特关系</th></tr></thead><tbody><tr><td><a href="/04_people/凯瑟琳·格雷厄姆.html">凯瑟琳·格雷厄姆</a></td><td>CEO/发行人</td><td>长期合作伙伴，巴菲特任董事期间</td></tr><tr><td>Phil Graham</td><td>前发行人</td><td>&quot;新闻是历史第一份草稿&quot;名言作者</td></tr><tr><td>唐纳德·格雷厄姆</td><td>后任CEO</td><td>凯瑟琳之子，延续了股东导向传统</td></tr><tr><td>Dick Simmons</td><td>高管</td><td>巴菲特在1988年股东信中提及</td></tr></tbody></table><h2 id="行业变迁与估值变化" tabindex="-1">行业变迁与估值变化 <a class="header-anchor" href="#行业变迁与估值变化" aria-label="Permalink to &quot;行业变迁与估值变化&quot;">​</a></h2><h3 id="_1990年代-媒体行业转折" tabindex="-1">1990年代：媒体行业转折 <a class="header-anchor" href="#_1990年代-媒体行业转折" aria-label="Permalink to &quot;1990年代：媒体行业转折&quot;">​</a></h3><p>巴菲特在1991年股东信中首次指出媒体行业估值逻辑的变化：</p><blockquote><p>&quot;几年前大家觉得，报纸电视台杂志，每年盈利不用加资本就能涨6%，折旧差不多等于资本开支，所以reported盈利就是自由现金流，所以一千万税后盈利，折现率10%，值两千五百万，现在预期不变，盈利就是围绕一千万波动，折现率还是10%，现在盈利就是一千万，现在值一个亿，所以估值一下子掉了一半多。&quot;</p></blockquote><h3 id="持仓态度" tabindex="-1">持仓态度 <a class="header-anchor" href="#持仓态度" aria-label="Permalink to &quot;持仓态度&quot;">​</a></h3><p>尽管认识到媒体行业变化，巴菲特仍坚持持有：</p><blockquote><p>&quot;我们重仓媒体，水牛城新闻，首都城市/ABC，华盛顿邮报，内在价值确实下降了，但是水牛城新闻斯坦·利普西管理得非常好，首都城市/ABC华盛顿邮报管理也非常棒，负债率很低，所以减值没那么夸张，我们没卖，我们原则就是不卖。&quot; —— 1991年股东信</p></blockquote><h3 id="_2000年代-持续持有" tabindex="-1">2000年代：持续持有 <a class="header-anchor" href="#_2000年代-持续持有" aria-label="Permalink to &quot;2000年代：持续持有&quot;">​</a></h3><p>尽管报纸行业面临互联网冲击，巴菲特在2000年代的股东信中继续持有华盛顿邮报，未进行大规模减持。</p><h2 id="投资回报分析" tabindex="-1">投资回报分析 <a class="header-anchor" href="#投资回报分析" aria-label="Permalink to &quot;投资回报分析&quot;">​</a></h2><p>假设1973年买入成本1,063万美元：</p><table tabindex="0"><thead><tr><th>年份</th><th>持股市值</th><th>年复利回报</th><th>增值倍数</th></tr></thead><tbody><tr><td>1985</td><td>2.21亿</td><td>约26%</td><td>约21倍</td></tr><tr><td>1987</td><td>3.26亿</td><td>约28%</td><td>约31倍</td></tr><tr><td>1996</td><td>5.79亿</td><td>约16%</td><td>约54倍</td></tr><tr><td>2006</td><td>12.88亿</td><td>约11%</td><td>约121倍</td></tr><tr><td>2013</td><td>约14亿</td><td>约12%</td><td>约132倍</td></tr></tbody></table><h3 id="关键投资节点回顾" tabindex="-1">关键投资节点回顾 <a class="header-anchor" href="#关键投资节点回顾" aria-label="Permalink to &quot;关键投资节点回顾&quot;">​</a></h3><p><strong>1973年：买入</strong></p><ul><li>成本：1,063万美元</li><li>市值：约1亿美元</li><li>内在价值：4-5亿美元</li><li>安全边际：75%</li></ul><p><strong>1985年：比例赎回</strong></p><ul><li>市值：2.21亿美元</li><li>特别分红：1,488万美元</li><li>持股数调整至1,727,765股</li></ul><p><strong>2013年：出售</strong></p><ul><li>出售价格：约14亿美元</li><li>持有年限：40年</li><li>总回报：超过100倍</li></ul><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p>华盛顿邮报在以下年份的股东信中被提及：</p><p><strong>1970年代</strong>：1975, 1977, 1978, 1979 <strong>1980年代</strong>：1980, 1981, 1982, 1984, 1985, 1986, 1987, 1988, 1989 <strong>1990年代</strong>：1990, 1991, 1992, 1993, 1994, 1995, 1996, 1997, 1998, 1999 <strong>2000年代</strong>：2000, 2001, 2002, 2003, 2004, 2005, 2006 <strong>2010年代</strong>：2013, 2019</p><h2 id="后续发展" tabindex="-1">后续发展 <a class="header-anchor" href="#后续发展" aria-label="Permalink to &quot;后续发展&quot;">​</a></h2><h3 id="_2013年报纸业务出售" tabindex="-1">2013年报纸业务出售 <a class="header-anchor" href="#_2013年报纸业务出售" aria-label="Permalink to &quot;2013年报纸业务出售&quot;">​</a></h3><p>2013年，华盛顿邮报公司将旗舰报纸《华盛顿邮报》出售给亚马逊创始人杰夫·贝索斯。公司更名为Graham Holdings，继续经营教育（Kaplan）、广播电视等业务。</p><h3 id="出售原因分析" tabindex="-1">出售原因分析 <a class="header-anchor" href="#出售原因分析" aria-label="Permalink to &quot;出售原因分析&quot;">​</a></h3><p>报纸业务面临的挑战使其不再是巴菲特最初投资时的&quot;垄断&quot;商业模式：</p><ul><li>互联网对传统报纸广告的冲击</li><li>读者获取信息方式的根本变化</li><li>报纸发行量和收入的持续下滑</li></ul><h3 id="巴菲特的态度" tabindex="-1">巴菲特的态度 <a class="header-anchor" href="#巴菲特的态度" aria-label="Permalink to &quot;巴菲特的态度&quot;">​</a></h3><p>巴菲特对此交易表示支持，认为这对股东是正确决定。他早在1991年就预见到媒体行业的变化：</p><blockquote><p>&quot;我们重仓媒体，水牛城新闻，首都城市/ABC，华盛顿邮报，内在价值确实下降了……我们没卖，我们原则就是不卖，就是我们觉得好企业，哪怕价值跌一点，还是拿着。&quot;</p></blockquote><p>但在2013年，当行业趋势明确后，巴菲特选择配合出售，体现了&quot;在别人恐惧时贪婪，在别人贪婪时恐惧&quot;的投资哲学。</p><h3 id="graham-holdings的后续" tabindex="-1">Graham Holdings的后续 <a class="header-anchor" href="#graham-holdings的后续" aria-label="Permalink to &quot;Graham Holdings的后续&quot;">​</a></h3><p>出售报纸业务后，Graham Holdings（股票代码GHC）继续作为一家多元化媒体和教育公司运营，Kaplan教育部门成为其重要业务板块。</p><h2 id="投资启示" tabindex="-1">投资启示 <a class="header-anchor" href="#投资启示" aria-label="Permalink to &quot;投资启示&quot;">​</a></h2><p>华盛顿邮报投资是巴菲特价值投资理念的典范案例：</p><ol><li><strong>安全边际</strong>：以内在价值四分之一的价格买入</li><li><strong>能力圈</strong>：巴菲特对报纸行业有深刻理解，年轻时曾送报赚取第一桶金</li><li><strong>长期持有</strong>：持有超过40年，穿越多个经济周期</li><li><strong>管理层质量</strong>：与优秀管理层（凯瑟琳·格雷厄姆）合作</li><li><strong>逆向投资</strong>：在市场恐慌时买入</li><li><strong>三重好处</strong>：内在价值增长 + 回购提升每股价值 + 估值修复</li></ol><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/search.html?q=首都城市ABC">首都城市ABC</a> - 同为媒体持仓</li><li><a href="/03_companies/水牛城新闻.html">水牛城新闻</a> - 伯克希尔控股报纸</li><li><a href="/03_companies/GEICO.html">GEICO</a> - 同为主要非控股持仓，与华盛顿邮报有个人渊源</li><li><a href="/04_people/凯瑟琳·格雷厄姆.html">凯瑟琳·格雷厄姆</a> - 华盛顿邮报CEO，巴菲特长期合作伙伴</li><li><a href="/03_companies/可口可乐.html">可口可乐</a> - 同为&quot;永久持仓&quot;</li></ul><hr><p><em>最后更新：2026-04-16</em></p><h2 id="相关信件" tabindex="-1">相关信件 <a class="header-anchor" href="#相关信件" aria-label="Permalink to &quot;相关信件&quot;">​</a></h2><ul><li><a href="./../01_letters/1975年/翻译.html">1975年</a></li><li><a href="./../01_letters/1977年/翻译.html">1977年</a></li><li><a href="./../01_letters/1978年/翻译.html">1978年</a></li><li><a href="./../01_letters/1979年/翻译.html">1979年</a></li><li><a href="./../01_letters/1980年/翻译.html">1980年</a></li><li><a href="./../01_letters/1981年/翻译.html">1981年</a></li><li><a href="./../01_letters/1982年/翻译.html">1982年</a></li><li><a href="./../01_letters/1984年/翻译.html">1984年</a></li><li><a href="./../01_letters/1985年/翻译.html">1985年</a></li><li><a href="./../01_letters/1986年/翻译.html">1986年</a></li><li><a href="./../01_letters/1987年/翻译.html">1987年</a></li><li><a href="./../01_letters/1988年/翻译.html">1988年</a></li><li><a href="./../01_letters/1989年/翻译.html">1989年</a></li><li><a href="./../01_letters/1990年/翻译.html">1990年</a></li><li><a href="./../01_letters/1991年/翻译.html">1991年</a></li><li><a href="./../01_letters/1992年/翻译.html">1992年</a></li><li><a href="./../01_letters/1993年/翻译.html">1993年</a></li><li><a href="./../01_letters/1994年/翻译.html">1994年</a></li><li><a href="./../01_letters/1995年/翻译.html">1995年</a></li><li><a href="./../01_letters/1996年/翻译.html">1996年</a></li><li><a href="./../01_letters/1997年/翻译.html">1997年</a></li><li><a href="./../01_letters/1998年/翻译.html">1998年</a></li><li><a href="./../01_letters/1999年/翻译.html">1999年</a></li><li><a href="./../01_letters/2000年/翻译.html">2000年</a></li><li><a href="./../01_letters/2001年/翻译.html">2001年</a></li><li><a href="./../01_letters/2002年/翻译.html">2002年</a></li><li><a href="./../01_letters/2003年/翻译.html">2003年</a></li><li><a href="./../01_letters/2004年/翻译.html">2004年</a></li><li><a href="./../01_letters/2005年/翻译.html">2005年</a></li><li><a href="./../01_letters/2006年/翻译.html">2006年</a></li><li><a href="./../01_letters/2013年/翻译.html">2013年</a></li><li><a href="./../01_letters/2019年/翻译.html">2019年</a></li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该公司在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/01_letters/1975年/翻译.html">/01_letters/1975年/翻译</a></li><li><a href="/01_letters/1977年/翻译.html">/01_letters/1977年/翻译</a></li><li><a href="/01_letters/翻译.html">/01_letters//翻译</a></li><li><a href="/01_letters/翻译.html">/01_letters//翻译</a></li></ul>',142)])])}const c=a(o,[["render",d]]);export{b as __pageData,c as default};
